// Package lockfile reads GitHub Actions workflow dependency lockfiles.
// https://docs.github.com/en/enterprise-cloud@latest/actions/concepts/security/workflow-dependency-lockfiles
package lockfile

import (
	"errors"
	"fmt"
	"io/fs"
	"path/filepath"
	"slices"

	parserlock "github.com/github/actions-lockfile/go/pkg/lockfile"
	"github.com/spf13/afero"
)

// Path is the path of the lockfile from the repository root.
const Path = parserlock.Path

// Lockfile is a workflow dependency lockfile generated by `gh actions-lock`.
type Lockfile struct {
	file parserlock.File
	// invalid is true if ghalint failed to read the lockfile.
	invalid bool
}

// Invalid returns a Lockfile representing a lockfile that ghalint failed to read.
// Its Locked regards every action that the lockfile can lock as locked,
// because they may be locked and the read error fails the run anyway.
func Invalid() *Lockfile {
	return &Lockfile{invalid: true}
}

// Read reads and validates the lockfile. It returns nil without an error if the lockfile doesn't exist.
func Read(afs afero.Fs) (*Lockfile, error) {
	b, err := afero.ReadFile(afs, Path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil //nolint:nilnil
		}
		return nil, fmt.Errorf("read a lockfile: %w", err)
	}
	return Parse(b)
}

// Parse parses and validates the content of a lockfile.
func Parse(b []byte) (*Lockfile, error) {
	f, err := parserlock.Parse(b)
	if err != nil {
		return nil, fmt.Errorf("parse a lockfile: %w", err)
	}
	return &Lockfile{file: f}, nil
}

// Locked reports whether the action uses is locked for the workflow.
// It returns false if lf is nil or uses isn't a repository action, such as a local action, a Docker image, or a reusable workflow.
// If lf is Invalid, it returns true for every repository action.
// The lockfile records actions as canonical keys `owner/repo@ref`, where owner and repo are lowercased and a sub-action path is dropped.
func (lf *Lockfile) Locked(workflowFilePath, uses string) bool {
	if lf == nil {
		return false
	}
	ref := parserlock.ParseActionRef(uses)
	if ref == nil {
		return false
	}
	if lf.invalid {
		return true
	}
	key := parserlock.IndexKey(ref.Owner, ref.Repo, ref.Ref)
	keys, ok := lf.file.LookupWorkflow(filepath.ToSlash(workflowFilePath))
	if !ok || !slices.Contains(keys, key) {
		return false
	}
	_, ok = lf.file.Dependencies[key]
	return ok
}
